// Package registry embeds the prebuilt Registry Data payload for protocol
// 767 (1.21.1) and the numeric registry ids derived from vanilla order.
//
// The payload is generated by docs/protocol/build_registries.py from the
// mcmeta registry dumps; see docs/protocol/README notes for regeneration.
package registry

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
	"sync"

	"atlas/internal/proto"
)

//go:embed biomes.json
var biomeData []byte

var biomeOnce sync.Once
var biomeNames []string
var biomeIDs map[string]int32
var biomeErr error

func loadBiomes() error {
	biomeOnce.Do(func() {
		biomeErr = json.Unmarshal(biomeData, &biomeNames)
		if biomeErr != nil {
			return
		}
		biomeIDs = make(map[string]int32, len(biomeNames))
		for id, name := range biomeNames {
			biomeIDs["minecraft:"+name] = int32(id)
		}
	})
	return biomeErr
}

func BiomeID(name string) (int32, error) {
	if err := loadBiomes(); err != nil {
		return 0, err
	}
	if !strings.Contains(name, ":") {
		name = "minecraft:" + name
	}
	id, ok := biomeIDs[name]
	if !ok {
		return 0, fmt.Errorf("unknown 1.21.1 biome %q", name)
	}
	return id, nil
}

func BiomeName(id int32) (string, error) {
	if err := loadBiomes(); err != nil {
		return "", err
	}
	if id < 0 || int(id) >= len(biomeNames) {
		return "", fmt.Errorf("invalid biome ID %d", id)
	}
	return "minecraft:" + biomeNames[id], nil
}

//go:embed registries.bin
var blob []byte

// The remaining configuration-phase payloads are captured verbatim from a
// vanilla 1.21.1 server (see cmd/atlas-capture), so the client sees exactly
// what it would from vanilla: feature flags, known-packs advertisement, and
// the full tag set.
//
//go:embed feature_flags.bin
var featureFlags []byte

//go:embed known_packs.bin
var knownPacks []byte

//go:embed tags.bin
var tags []byte

// FeatureFlags returns the vanilla Feature Flags payload.
func FeatureFlags() []byte { return featureFlags }

// KnownPacks returns the vanilla Known Packs (clientbound) payload.
func KnownPacks() []byte { return knownPacks }

// Tags returns the vanilla Update Tags payload.
func Tags() []byte { return tags }

// Packets returns the individual Configuration-phase Registry Data packet
// payloads. Since 1.20.5 the client expects ONE packet per registry:
// Identifier(registry) + Prefixed Array of {Identifier entry, Optional NBT}.
// The embedded blob is a container: VarInt count, then per packet
// VarInt length + payload bytes.
func Packets() [][]byte {
	r := proto.NewReader(blob)
	n, err := r.VarInt()
	if err != nil {
		panic("registry: corrupt embedded blob")
	}
	out := make([][]byte, 0, n)
	for i := int32(0); i < n; i++ {
		l, err := r.VarInt()
		if err != nil {
			panic("registry: corrupt embedded blob")
		}
		b, err := r.Bytes(int(l))
		if err != nil {
			panic("registry: corrupt embedded blob")
		}
		out = append(out, b)
	}
	return out
}

// Numeric ids in vanilla 1.21.1 registry order.
const (
	DimOverworld   = 0 // dimension_type
	BiomePlains    = 39
	EntityPlayerID = 82 // entity_type index of "player"
)
